/* games/service-medals.js  |  PF v1.4.1 | Service Medals sticky layer over all homepage games (event-driven)
   KILL: ?pf_off=service-medals  or  localStorage pf_disabled_v1='["service-medals"]' */

(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip("service-medals")) { return; }
  try {
    /* PF SERVICE MEDALS v2 — sticky collection layer over all 12 homepage games.
       Listens for pf-* CustomEvents. Awards one medal per game per week
       (America/Chicago, Monday reset). All 16 in a week = FULL DEPLOYMENT:
       +50 XP via ranks backend (idempotent per week) + callsign etched on the
       Vanguard Wall. Device-local medal tracking (pf_medals_v2) + backend for XP. */
    (function(){
    'use strict';
    if(window.pfMedalsLoaded)return;window.pfMedalsLoaded=true;
    var LS='pf_medals_v2',LS_I='pf_identity_v1';
    var BACKEND_URL=(window.PF_BACKEND_URL);
    
    var MEDALS=[
     {id:'vote',    glyph:'\u2605', name:'Ballot',          ev:'pf-vote-cast'},
     {id:'ballot',  glyph:'\u2622', name:'Bracket Ballot',  ev:'pf-bracket-ballot'},
     {id:'bracket', glyph:'\u2620', name:'Liquidator',      ev:'pf-bracket-liquidated'},
     {id:'caption', glyph:'\u270E', name:'Word Warrior',    ev:'pf-caption-submit'},
     {id:'poster',  glyph:'\u25C8', name:'Press Pass',      ev:'pf-poster-made'},
     {id:'quiz',    glyph:'\u25C9', name:'Intel Operative', ev:'pf-quiz-done'},
     {id:'billionaire', glyph:'\uFF04', name:'Billionaire Spotter', ev:'pf-billionaire-answered'},
     {id:'interrogation', glyph:'\u2754', name:'Interrogator', ev:'pf-interrogation-answered'},
     {id:'orders',  glyph:'\u25B2', name:'Field Duty',      ev:'pf-order-checkin'},
     {id:'drop',    glyph:'\u25CF', name:'Supply Runner',   ev:'pf-drop-claimed'},
     {id:'enlisted',glyph:'\u2694', name:'Enlisted',        ev:'pf-enlisted'},
     {id:'guess',   glyph:'\u25CE', name:'Profiler',        ev:'pf-guess-done'},
     {id:'raid',    glyph:'\u26A1', name:'Raider',           ev:'pf-raid-report'},
     {id:'infight', glyph:'\uD83E\uDD4A', name:'Brawler',          ev:'pf-infight-fire'},
     /* REDISTRIBUTION LAYER (2026-10-05): the retired casino hall's
        'High Roller' medal (ev pf-casino-cashed, which can never fire again
        — casino.js is unmounted) was removed with it. The redistribution
        layer's medal is below. Event name 'pf-wm-settled' stays (stability). */
     /* Redistribution layer 'Market Maker' (CEO decision: name stays).
        Earned by the first settled redistribution-layer event each week —
        forecast, gambit, raid, or draw (win or loss) — REQUIRED for
        FULL DEPLOYMENT. */
     {id:'whitemarket', glyph:'\uD83C\uDFB2', name:'Market Maker',  ev:'pf-wm-settled'},
     /* 2026-10-05: CIVIC DUTY — 3-of-5 distinct civic actions in a week
        (petition signed/created, rep contacted, voter pledged/checked).
        Event 'pf-civic-duty-earned' is fired by games/civic-duty.js after its
        own threshold gate (service-medals.js never listens for the 5 raw
        pf-civic-* events directly — the gate keeps them out of the weekly
        rack until qualified). REQUIRED for FULL DEPLOYMENT like the rest. */
     {id:'civic', glyph:'\uD83D\uDDF3', name:'Civic Duty', ev:'pf-civic-duty-earned'}
    ];
    /* A5 (2026-10-05): SCOUT — persistent (non-weekly) achievement medal.
       Awarded at 6 distinct creator catalog views (pf-scout-earned, fired by
       pages/slr-catalog.js). It never resets and NEVER counts toward the
       weekly FULL DEPLOYMENT — the rack below stays strictly weekly. */
    var ACHV=[{id:'scout', glyph:'\u2691', name:'Scout'}];
    var LS_A='pf_medals_achv_v1';
    function loadAchv(){try{var s=JSON.parse(localStorage.getItem(LS_A)||'null');if(s&&typeof s==='object')return s;}catch(e){}return {};}
    function saveAchv(s){try{localStorage.setItem(LS_A,JSON.stringify(s));}catch(e){}}
    function load(){try{var s=JSON.parse(localStorage.getItem(LS)||'null');if(s&&s.w)return s;}catch(e){}return{w:PF.isoWeekKey(PF.chiNow()),m:{},fd:false};}
    function save(s){try{localStorage.setItem(LS,JSON.stringify(s));}catch(e){}}
    function callsign(){try{return String(JSON.parse(localStorage.getItem(LS_I)||'{}').callsign||'').toLowerCase();}catch(e){return '';}}
    /* JSONP GET (same pattern as ranks apiPost — avoids Apps Script POST redirect bug) */
    function apiGet(params,cb){
      if(!BACKEND_URL){cb(null);return;}
      var cbn='pfm'+Date.now()+Math.floor(Math.random()*1e6);
      window[cbn]=function(d){try{delete window[cbn];}catch(e){}try{scr.parentNode.removeChild(scr);}catch(e){}cb(d);};
      var q='?callback='+encodeURIComponent(cbn);
      for(var k in params){if(params.hasOwnProperty(k))q+='&'+encodeURIComponent(k)+'='+encodeURIComponent(params[k]);}
      var scr=document.createElement('script');scr.src=BACKEND_URL+q;scr.onerror=function(){cb(null);};
      (document.head||document.documentElement).appendChild(scr);
      setTimeout(function(){if(window[cbn]){try{delete window[cbn];}catch(e){}cb(null);}},15000);
    }
    
    /* Deploy medal is POST-only (backend auth layer). No type field. */
    function apiPostDeploy(cs,cb){
      var backend='';
      try{ backend=window.PF_BACKEND_URL||BACKEND_URL||''; }catch(e){ backend=BACKEND_URL||''; }
      if(!backend){ cb(null); return; }
      var body={action:'deploy',callsign:cs};
      try{ if(window.PFDeviceId) body.device=window.PFDeviceId()||''; }catch(e){}
      if(window.PF&&PF.authPost){ PF.authPost(backend,body,cb); return; }
      /* Fallback: raw POST with secret if available. */
      try{ var sec=window.PF&&PF.getAuthSecret?PF.getAuthSecret():''; if(sec) body.auth_secret=sec; }catch(e2){}
      try{
        fetch(backend,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
          .then(function(r){ return r.json(); })
          .then(function(j){ cb(j); })
          .catch(function(){ cb(null); });
      }catch(e3){ cb(null); }
    }

    function fullDeployment(s){
      if(s.fd||s.fd_pending)return;
      var cs=callsign();
      if(cs){
        /* backend: +50 XP (once/week, idempotent) + wall etch; fd=true only on confirmed success */
        apiPostDeploy(cs,function(j){
          if(j&&j.ok){s.fd=true;save(s);}
                    try{document.dispatchEvent(new CustomEvent('pf-do-update'));}catch(e){}
          renderRack();
        });
      }else{
        /* no callsign yet — bank XP locally, mark pending; backend deploy fires on claim.
           The pending key is stored so the flush can reverse the local +50
           exactly-once (the backend grant mirrors back via the ledger). */
        var pkey='medal_fd_'+s.w;
        s.fd_pending=pkey;save(s);
        /* Bank XP locally via the shared ledger (exactly-once per pkey). */
        try{ if(window.PF&&PF.creditLocal) PF.creditLocal(pkey,50); }catch(e){}
      }
      renderRack();
      /* M1 dopamine: the full weekly set is the crown — biggest celebration on the site. */
      try{ if(window.PF&&PF.dope){ var fdh=document.getElementById('pf-medals')||document.body; PF.dope.confetti(fdh,110); PF.dope.ping(fdh,'FULL DEPLOYMENT'); PF.dope.xpFloat(fdh,'+50 XP'); } }catch(dpe2){}
      try{document.dispatchEvent(new CustomEvent('pf-do-update'));}catch(e){}
    }
    /* flush a pending Full Deployment once the user claims a callsign.
       Exactly-once: reverse the local +50 banked earlier, because the backend
       deploy grant mirrors back via the ledger. Keeping both = +100. */
    function flushPendingDeploy(cs){
      var s=load();
      if(!s.fd_pending||s.fd)return;
      var pkey=typeof s.fd_pending==='string'?s.fd_pending:('medal_fd_'+s.w);
      apiPostDeploy(cs,function(j){
        if(!(j&&j.ok))return; /* keep fd_pending so a later claim retries */
        var s2=load();
        s2.fd=true;s2.fd_pending=false;save(s2);
        /* Exactly-once reversal of the banked +50: only debits if pkey was
           previously credited (mirrors the old got-key check). */
        try{ if(window.PF&&PF.debitLocal) PF.debitLocal(pkey,50); }catch(e){}
        try{document.dispatchEvent(new CustomEvent('pf-do-update'));}catch(e){}
        renderRack();
      });
    }
    document.addEventListener('pf-callsign-claimed',function(e){
      var cs=e&&e.detail&&e.detail.callsign?String(e.detail.callsign).toLowerCase():'';
      if(cs)flushPendingDeploy(cs);
    });
    var CSS='#pf-medals{margin:18px 0 4px;padding:14px 10px;border:2px dashed #c1121f;background:#141414}'+
    '#pf-medals .pm-title{font-family:\'Arial Black\',Arial,sans-serif;color:#ff5a00;font-size:14px;letter-spacing:3px;text-transform:uppercase;margin-bottom:10px}'+
    '#pf-medals .pm-title span{color:#c9bfa8;font-family:Arial,sans-serif;font-size:11px;letter-spacing:2px}'+
    '#pf-medals .pm-rack{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:10px}'+
    '#pf-medals .pm-m{width:62px;text-align:center;font-family:Arial,sans-serif}'+
    '#pf-medals .pm-g{font-size:24px;line-height:1;display:block;margin-bottom:4px}'+
    '#pf-medals .pm-m.got .pm-g{color:#ff5a00;text-shadow:0 0 8px rgba(255,90,0,.6)}'+
    '#pf-medals .pm-m.miss .pm-g{color:#3a3a3a}'+
    '#pf-medals .pm-n{font-size:8px;letter-spacing:1px;text-transform:uppercase;color:#c9bfa8}'+
    '#pf-medals .pm-m.miss .pm-n{color:#555}'+
    '#pf-medals .pm-note{font-family:Arial,sans-serif;font-size:11px;color:#c9bfa8;letter-spacing:1px}'+
    '#pf-medals .pm-note b{color:#ff5a00}'+
    '#pf-medals .pm-fd{font-family:\'Arial Black\',Arial,sans-serif;color:#f5ead6;background:#c1121f;display:inline-block;padding:6px 14px;margin-top:8px;font-size:13px;letter-spacing:2px}';
    function ensureCss(){
      if(document.getElementById('pf-medals-css'))return;
      var st=document.createElement('style');st.id='pf-medals-css';st.textContent=CSS;
      (document.head||document.documentElement).appendChild(st);
    }
    
    function renderRack(){
      ensureCss();
      var host=document.getElementById('pf-ranks');if(!host)return false;
      var s=load(),wk=PF.isoWeekKey(PF.chiNow());
      if(s.w!==wk){s={w:wk,m:{},fd:false};save(s);}
      var el=document.getElementById('pf-medals');
      if(!el){
        el=document.createElement('div');el.id='pf-medals';
        var anchor=document.getElementById('rNext');
        if(anchor&&anchor.parentNode)anchor.parentNode.insertBefore(el,anchor.nextSibling);
        else host.appendChild(el);
      }
      var h='<div class=\"pm-title\">\u2694 Service Medals <span>\u2014 this week</span></div><div class=\"pm-rack\">';
      var got=0;
      MEDALS.forEach(function(md){
        var has=!!s.m[md.id];if(has)got++;
        h+='<div class=\"pm-m '+(has?'got':'miss')+'\"><span class=\"pm-g\">'+md.glyph+'</span><span class=\"pm-n\">'+md.name+'</span></div>';
      });
      h+='</div>';
      if(s.fd){
        h+='<div class=\"pm-fd\">\u2605 FULL DEPLOYMENT \u2605</div><div class=\"pm-note\">All '+MEDALS.length+' earned. <b>+50 XP</b> banked, name on the wall. See you Monday.</div>';
      }else{
        h+='<div class=\"pm-note\">Earn all <b>'+MEDALS.length+'</b> this week for <b>FULL DEPLOYMENT</b>: +50 XP + your callsign on the Vanguard Wall. <b>'+got+'/'+MEDALS.length+'</b> so far.</div>';
      }
      /* A5 (2026-10-05): persistent campaign medals — outside the weekly
         rack. SCOUT never resets and never counts toward FULL DEPLOYMENT. */
      var achv=loadAchv(), ah='';
      ACHV.forEach(function(md){
        var has=!!achv[md.id];
        ah+='<div class=\"pm-m '+(has?'got':'miss')+'\"><span class=\"pm-g\">'+md.glyph+'</span><span class=\"pm-n\">'+md.name+'</span></div>';
      });
      h+='<div class=\"pm-title\" style=\"margin-top:12px\">\u2694 Campaign Medals <span>\u2014 persistent, never reset</span></div><div class=\"pm-rack\">'+ah+'</div>';
      if(!achv.scout) h+='<div class=\"pm-note\">Scout the roster: view <b>6</b> different fighters\u2019 catalog pages to earn SCOUT.</div>';
      el.innerHTML=h;
      /* 2026-10-06 share-everywhere. */
      try{ if(window.PFShareEverywhere) PFShareEverywhere.bar(el,'achievements',{link:'/'}); }catch(e){}
      return true;
    }
    function checkFull(s){
      if(s.fd||s.fd_pending)return;
      for(var i=0;i<MEDALS.length;i++){if(!s.m[MEDALS[i].id])return;}
      fullDeployment(s);
    }
    
    MEDALS.forEach(function(md){
      document.addEventListener(md.ev,function(){
        var s=load(),wk=PF.isoWeekKey(PF.chiNow());
        if(s.w!==wk){s={w:wk,m:{},fd:false};}
        var fresh=!s.m[md.id];
        if(fresh){s.m[md.id]=1;save(s);}
        /* M1 dopamine: earning a medal should feel earned. */
        try{ if(fresh&&window.PF&&PF.dope){ var mh=document.getElementById('pf-medals')||document.body; PF.dope.confetti(mh,40); PF.dope.ping(mh,'MEDAL EARNED: '+String(md.name||'').toUpperCase()); } }catch(dpe){}
        checkFull(s);
        renderRack();
      });
    });
    
    /* if the user enlists mid-week, award the Enlisted medal retroactively */
    document.addEventListener('pf-enlisted',function(){
      var s=load(),wk=PF.isoWeekKey(PF.chiNow());
      if(s.w!==wk){s={w:wk,m:{},fd:false};}
      /* already handled by the MEDALS loop above; this is a no-op safeguard */
    });

    /* A5 (2026-10-05): SCOUT award — persistent bucket, exactly-once. */
    document.addEventListener('pf-scout-earned',function(){
      var a=loadAchv();
      if(a.scout)return;
      a.scout=1;saveAchv(a);
      /* M1 dopamine: earning a medal should feel earned. */
      try{ if(window.PF&&PF.dope){ var mh=document.getElementById('pf-medals')||document.body; PF.dope.confetti(mh,60); PF.dope.ping(mh,'MEDAL EARNED: SCOUT'); } }catch(dpe){}
      renderRack();
    });
    
    /* mount the rack once the ranks widget exists */
    var tries=0;
    function mount(){
      /* 2026-10-05: cross-page medal check — Civic Duty is earned on
         /political-hq (bundle-hq), where this file never loads. If it
         completed the set before the rack mounted here, checkFull fires
         FULL DEPLOYMENT now. checkFull is a no-op when any medal is
         missing or fd/fd_pending is already set — safe to call every mount. */
      if(renderRack()){ try{ checkFull(load()); }catch(e){} return; }
      if(++tries<20)setTimeout(mount,1000);
    }
    if(document.readyState==='complete'||document.readyState==='interactive')mount();
    else document.addEventListener('DOMContentLoaded',mount);
    })();
  } catch (err) { PF.error("service-medals", err); }
})();

;

/* ===== first-wave.js ===== */
/* games/first-wave.js  |  PF v1.4.3 | LAUNCH WEEK — "FIRST WAVE".
   Pre-launch countdown banner (T-3d -> T-0), live-week banner, founder badge
   ("FIRST WAVE" / "You were here when it started."), the 7-day launch
   circuit card, and the public founder roll board.
   READ-ONLY. ZERO XP — this module mints nothing, multiplies nothing, moves
   no XP (Economy Desk sign-off condition). Circuit progress is derived
   server-side; the module writes nothing. Founder markers are status-only
   (rendered from launchweek_status, no ribbon-table writes in v1).
   Backend contract (src/launchweek.js, parallel wave):
     launchweek_status (auth: own callsign) -> {launched, founder, circuit:[7],
       cohort_size, full_muster, launch_ts, phase?}
     launchweek_roll   (public, capped 200) -> {founders:[{callsign,
       full_muster}], ...}
   CONTRACT DEVIATION (frontend side, for the backend wave): the pre-launch
   countdown is an explicit requirement, but launched:false means dormant.
   This module resolves it as: launched:false + launch_ts set and within
   T-3d..T-0 -> countdown banner; launched:false + launch_ts absent/0 ->
   render nothing, exit. The backend must therefore return launch_ts in
   launchweek_status even before launch. N is computed client-side from
   launch_ts vs now (America/Chicago) when the server does not send
   countdown_days. Grammar deviation: "{N} DAY." when N==1.
   Banners follow the existing siren/banner pattern (cf. briefing-siren.js):
   fixed top bar, site-wide, additive — never a modal, never a funnel
   hijack. The first-60-seconds mission keeps priority for anonymous
   visitors; this banner layers alongside it.
   KILL: ?pf_off=first-wave  or  localStorage pf_disabled_v1='["first-wave"]' */
(function () {
  'use strict';
  var PF = window.PF;
  var KILL = 'first-wave';
  if (!PF || PF.skip(KILL)) { return; }
  try {
    var href = window.location.href || '';
    if (/\/config\//.test(href)) return;
    var bd = document.body;
    if (bd && (bd.classList.contains('sqs-edit-mode') || bd.classList.contains('sqs-editing'))) return;
  } catch (e) {}

  var BACKEND = window.PF_BACKEND_URL;
  var DAY = 86400000;
  var PHASE = null;           /* 'countdown' | 'live' | 'ended' */
  var STATUS = null;          /* launchweek_status payload */

  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;')
      .replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function $(id) { try { return document.getElementById(id); } catch (e) { return null; } }
  function ident() {
    var cs = '', dev = '';
    try { cs = window.PFCallsign ? window.PFCallsign() : ''; } catch (e) {}
    try { dev = window.PFDeviceId ? window.PFDeviceId() : ''; } catch (e) {}
    return { callsign: String(cs || '').toLowerCase(), device: String(dev || '') };
  }

  /* Mirror core/rites.js serverCompleted: dispatch pair
     ('launchweek','lw_action'), POST via PF.postAction, 6s cap. */
  function postStatus(params, cb) {
    var done = false;
    function fin(j) { if (done) return; done = true; try { cb(j); } catch (e) {} }
    try {
      if (!(window.PF && PF.postAction)) { fin(null); return; }
      var to = setTimeout(function () { fin(null); }, 6000);
      PF.postAction('launchweek', 'lw_action', 'launchweek_status', params || {}, function (j) {
        try { clearTimeout(to); } catch (e2) {}
        fin(j);
      });
    } catch (e) { fin(null); }
  }

  /* Resolve the launch phase. Backend `phase` is authoritative when present;
     otherwise derive from launch_ts vs now. Countdown surface only
     T-3d..T-0 per spec; window is 7 days from launch_ts. */
  function resolvePhase(j) {
    try {
      if (j && (j.phase === 'countdown' || j.phase === 'live' || j.phase === 'ended')) return j.phase;
    } catch (e) {}
    var ts = 0;
    try { ts = Number(j && j.launch_ts) || 0; } catch (e2) {}
    if (!ts) return 'dormant';
    var now = Date.now();
    if (j && j.launched === true) {
      return now > ts + 7 * DAY ? 'ended' : 'live';
    }
    if (now < ts - 3 * DAY) return 'dormant';
    if (now < ts) return 'countdown';
    if (now <= ts + 7 * DAY) return 'live';
    return 'ended';
  }

  /* N from launch_ts vs now (America/Chicago). Countdown only shows in the
     T-3d..T-0 window, so diff is positive and <= 3 days here. */
  function countdownDays(ts) {
    var diff = Number(ts) - Date.now();
    var n = Math.ceil(diff / DAY);
    if (n < 1) n = 1;
    if (n > 3) n = 3;
    return n;
  }

  /* ---------- Banner (countdown + live) ---------- */
  function renderBanner() {
    if ($('pf-firstwave-bar')) return;
    var head = '', sub = '';
    if (PHASE === 'countdown') {
      var ts = 0, n = 3;
      try {
        if (STATUS && STATUS.countdown_days != null) { n = Math.max(1, Math.min(3, Number(STATUS.countdown_days) || 1)); }
        else { ts = Number(STATUS.launch_ts) || 0; n = countdownDays(ts); }
      } catch (e) {}
      head = 'THE FIRST WAVE LANDS IN ' + n + ' DAY' + (n === 1 ? '.' : 'S.');
      sub = 'Be here when the first shot fires.';
    } else {
      head = 'THE FIRST WAVE IS HERE.';
      sub = 'Enlist this week. Founders are forever.';
    }
    var bar = document.createElement('div');
    bar.id = 'pf-firstwave-bar';
    bar.setAttribute('role', 'status');
    bar.setAttribute('aria-label', 'First Wave launch banner');
    bar.innerHTML =
      '<div style="max-width:1100px;margin:0 auto;padding:12px 16px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;box-sizing:border-box;">'
      + '<span style="color:#e5383b;font-weight:900;letter-spacing:0.25em;font-size:0.7rem;">&#9733; FIRST WAVE &#9733;</span>'
      + '<span style="color:#f5ead6;font-weight:900;font-size:1.05rem;letter-spacing:0.06em;">' + esc(head) + '</span>'
      + '<span style="color:#c9bfa8;font-size:0.9rem;">' + esc(sub) + '</span>'
      + '</div>';
    try {
      bar.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99990;background:#0b0b0c;'
        + 'border-bottom:3px solid #c1121f;font-family:\'Helvetica Neue\',Arial,sans-serif;box-sizing:border-box;'
        + 'box-shadow:0 2px 18px rgba(193,18,31,0.45);';
      document.body.insertBefore(bar, document.body.firstChild);
    } catch (e) {}
  }

  /* ---------- Founder badge ---------- */
  function renderFounder() {
    if (!$('pf-firstwave-founder')) {
      /* Clearly-marked slot: the founder badge lives here. Other surfaces
         (enlistment papers, profile widgets) can relocate or clone this
         slot's content; this module never touches their markup. */
      var host = $('pf-ranks');
      if (host && host.parentNode) {
        try {
          var slot = document.createElement('div');
          slot.id = 'pf-firstwave-founder';
          slot.setAttribute('data-founder-slot', 'first-wave');
          slot.innerHTML =
            '<div style="display:inline-block;background:#0b0b0c;border:2px solid #c1121f;'
            + 'padding:10px 18px;margin:10px auto;font-family:\'Helvetica Neue\',Arial,sans-serif;text-align:center;">'
            + '<div style="color:#e5383b;font-weight:900;letter-spacing:0.3em;font-size:0.72rem;">FIRST WAVE</div>'
            + '<div style="color:#c9bfa8;font-size:0.85rem;margin-top:4px;">You were here when it started.</div>'
            + '</div>';
          host.parentNode.insertBefore(slot, host.nextSibling);
        } catch (e) {}
      }
    }
    /* Signal for other surfaces (enlistment papers area, profiles, walls):
       a founder is on the page. Listeners mount their own rendering — this
       module does not duplicate the ENLISTED ceremony or claim flow. */
    try {
      var id = ident();
      var ev = new CustomEvent('pf-firstwave-founder', {
        detail: {
          callsign: id.callsign,
          fullMuster: !!(STATUS && STATUS.full_muster),
          cohortSize: (STATUS && STATUS.cohort_size) || 0
        }
      });
      window.dispatchEvent(ev);
    } catch (e2) {}
  }

  /* ---------- Circuit card ---------- */
  var CIRCUIT = [
    { day: 1, name: 'ENLIST', sub: 'Claim your callsign. Take the name.', url: '/', key: 'enlist' },
    { day: 2, name: 'REPORT FOR DAILY ORDERS', sub: 'Complete today\u2019s missions.', url: '/', key: 'daily-orders' },
    { day: 3, name: 'JOIN A CELL', sub: 'No lone wolves. Get a squad.', url: '/cells', key: 'cells' },
    { day: 4, name: 'CAST THE FAN VOTE', sub: 'Back your propagandist of the week.', url: '/', key: 'fan-vote' },
    { day: 5, name: 'WALK THE ROUTE MARCH', sub: 'Hit today\u2019s march stops.', url: null, key: 'route-march' },
    { day: 6, name: 'RECRUIT A FIGHTER', sub: 'Share your recruit link. Bring them in.', url: '/', key: 'recruit' },
    { day: 7, name: 'FUND THE FIGHT', sub: 'Put money on the movement.', url: '/ventures', key: 'ventures' }
  ];
  /* Deep links verified against the merged tree (2026-10-05): '/' = homepage
     (enlistment-ranks claim, Daily Orders, referral share, fan-vote all mount
     there), '/cells' = rites.js ENLISTED CTA href, '/ventures' =
     bundle-warchest movement finance page (BLOSSOM M3 2026-10-06: the
     movement silo now mounts on /ventures as the Movement Funds section).
     Day 5 resolves at runtime from the route-march circuit_status read
     (same action core/22-routemarch.js uses);
     fallback '/events'. No invented URLs. */
  function rmLink(cb) {
    function done(url) { try { cb(url || '/events'); } catch (e) {} }
    try {
      if (!BACKEND) { done(null); return; }
      var fn = 'pfFwRmCb' + Math.floor(Math.random() * 1e9);
      var s = document.createElement('script'), fin = false;
      function finish(j) {
        if (fin) return; fin = true;
        try { delete window[fn]; } catch (e2) {}
        try { if (s.parentNode) s.parentNode.removeChild(s); } catch (e3) {}
        var url = null;
        try {
          var stops = (j && j.ok && j.stops) || [];
          var id = ident();
          for (var i = 0; i < stops.length; i++) {
            if (stops[i] && stops[i].page && !stops[i].done) { url = stops[i].page; break; }
          }
          if (!url && stops.length && stops[0] && stops[0].page) url = stops[0].page;
        } catch (e4) {}
        done(url);
      }
      window[fn] = function (j) { finish(j); };
      s.onerror = function () { finish(null); };
      var id2 = ident(), q = '?action=' + encodeURIComponent('circuit_status');
      if (id2.callsign) q += '&callsign=' + encodeURIComponent(id2.callsign);
      if (id2.device) q += '&device=' + encodeURIComponent(id2.device);
      try {
        var sec = (window.PF && PF.getAuthSecret) ? PF.getAuthSecret() : '';
        if (sec) q += '&auth_secret=' + encodeURIComponent(sec);
      } catch (e5) {}
      q += '&callback=' + fn;
      s.src = BACKEND + q;
      document.head.appendChild(s);
      setTimeout(function () { finish(null); }, 12000);
    } catch (e6) { done(null); }
  }

  function renderCircuit() {
    if ($('pf-firstwave-circuit')) return;
    var states = [];
    try {
      var c = (STATUS && STATUS.circuit) || [];
      for (var i = 0; i < 7; i++) states.push(!!c[i]);
    } catch (e) { for (var k = 0; k < 7; k++) states.push(false); }
    var allDone = states.every(function (b) { return b; });

    function mountCard(rmUrl) {
      if ($('pf-firstwave-circuit')) return;
      var rows = '';
      for (var d = 0; d < 7; d++) {
        var day = CIRCUIT[d], doneD = states[d];
        var url = (day.key === 'route-march') ? rmUrl : day.url;
        /* Day 5 resolves asynchronously from circuit_status; the row renders
           immediately with the fallback and upgrades when the read lands. */
        var linkId = (day.key === 'route-march') ? ' id="pf-fw-day5-link"' : '';
        var tag = doneD
          ? '<span style="color:#7ddf8a;font-weight:900;">&#10003; DONE</span>'
          : '<span style="color:#e5383b;font-weight:900;">&#9679; OPEN</span>';
        var stake = (day.key === 'ventures')
          ? '<div style="color:#8a8172;font-size:0.72rem;margin-top:6px;">XP has no cash value. Stakes are final.</div>'
          : '';
        rows +=
          '<div style="display:flex;align-items:center;gap:12px;padding:10px 4px;border-top:1px solid #2a2a2a;">'
          + '<div style="min-width:44px;color:#e5383b;font-weight:900;font-size:0.8rem;letter-spacing:0.1em;">DAY ' + day.day + '</div>'
          + '<div style="flex:1;min-width:0;">'
          + '<a' + linkId + ' href="' + esc(url) + '" style="color:#f5ead6;font-weight:900;font-size:0.95rem;text-decoration:none;letter-spacing:0.04em;">' + esc(day.name) + ' &rarr;</a>'
          + '<div style="color:#a89e88;font-size:0.8rem;margin-top:2px;">' + esc(day.sub) + '</div>'
          + stake
          + '</div>'
          + '<div style="font-size:0.75rem;letter-spacing:0.08em;white-space:nowrap;">' + tag + '</div>'
          + '</div>';
      }
      var head = allDone
        ? '<div style="color:#7ddf8a;font-weight:900;letter-spacing:0.2em;font-size:0.78rem;">&#9733; FIRST WAVE &#8212; FULL MUSTER &#9733;</div>'
          + '<div style="color:#f5ead6;font-weight:900;font-size:1.25rem;margin-top:6px;letter-spacing:0.05em;">YOU STOOD ALL SEVEN.</div>'
        : '<div style="color:#e5383b;font-weight:900;letter-spacing:0.25em;font-size:0.78rem;">&#9733; THE FIRST WAVE CIRCUIT &#9733;</div>'
          + '<div style="color:#f5ead6;font-weight:900;font-size:1.25rem;margin-top:6px;letter-spacing:0.05em;">SEVEN DAYS. SEVEN ACTIONS. FOUNDERS FINISH.</div>';
      var el = document.createElement('div');
      el.id = 'pf-firstwave-circuit';
      el.innerHTML =
        '<div style="background:#0b0b0c;border:3px solid #c1121f;padding:18px 16px;max-width:680px;margin:18px auto;'
        + 'color:#f5ead6;font-family:\'Helvetica Neue\',Arial,sans-serif;box-sizing:border-box;">'
        + head
        + '<div style="color:#a89e88;font-size:0.85rem;margin-top:6px;">One prescribed action per day. The window closes &#8212; what\u2019s done is done.</div>'
        + '<div style="margin-top:10px;">' + rows + '</div>'
        + '</div>';
      /* Homepage leg: just after the START HERE header; /cells leg: after
         the cell-war standings (war-room mount, mirrors war-room-ticker.js). */
      try {
        var h = $('pf-v2');
        if (h) {
          var ph = h.querySelector('.pf-section-head[data-sec="start-here"]');
          if (ph && ph.parentNode) { ph.parentNode.insertBefore(el, ph.nextSibling); return; }
          h.insertBefore(el, h.firstChild); return;
        }
        var cp = $('pf-cells-page');
        if (cp) {
          var cw = cp.querySelector('section[data-game="cell-war"]');
          if (cw && cw.parentNode) { cw.parentNode.insertBefore(el, cw.nextSibling); return; }
          cp.appendChild(el); return;
        }
      } catch (e2) {}
    }

    /* Day 5 resolves from the route-march circuit_status read; render the
       card immediately with the fallback and upgrade the link when it
       lands (bounded, fail-silent). */
    var rmUrl = '/events';
    mountCard(rmUrl);
    rmLink(function (url) {
      try {
        if (!url || url === rmUrl) return;
        var a = $('pf-fw-day5-link');
        if (a) a.setAttribute('href', url);
      } catch (e2) {}
    });
  }

  /* ---------- Roll board ---------- */
  function renderRoll() {
    function paint(founders) {
      try {
        if ($('pf-firstwave-roll')) return;
        var list = (founders || []).slice(0, 200);
        var rows = '';
        for (var i = 0; i < list.length; i++) {
          var f = list[i] || {};
          var cs = String(f.callsign || '').toUpperCase();
          if (!cs) continue;
          var fm = !!f.full_muster;
          rows += '<div style="display:flex;align-items:baseline;gap:10px;padding:7px 4px;border-top:1px solid #2a2a2a;">'
            + '<span style="color:#f5ead6;font-weight:800;font-size:0.9rem;letter-spacing:0.06em;">' + esc(cs) + '</span>'
            + (fm ? '<span style="color:#7ddf8a;font-size:0.72rem;font-weight:900;letter-spacing:0.12em;">&#9733; FULL MUSTER</span>' : '')
            + '</div>';
        }
        var el = document.createElement('div');
        el.id = 'pf-firstwave-roll';
        el.innerHTML =
          '<div style="background:#0a0a0a;border-top:3px solid #c1121f;border-bottom:3px solid #c1121f;'
          + 'padding:22px 16px;max-width:1100px;margin:18px auto;color:#f5ead6;'
          + 'font-family:\'Helvetica Neue\',Arial,sans-serif;box-sizing:border-box;text-align:center;">'
          + '<div style="color:#e5383b;font-weight:900;letter-spacing:0.3em;font-size:0.72rem;">&#9733; THE FOUNDER ROLL &#9733;</div>'
          + '<div style="color:#f5ead6;font-weight:900;font-size:1.3rem;margin:8px 0 4px;letter-spacing:0.05em;">THEY WERE HERE WHEN IT STARTED.</div>'
          + '<div style="color:#a89e88;font-size:0.85rem;margin-bottom:10px;">This roll is closed forever. No late entries. No exceptions.</div>'
          + '<div style="max-width:560px;margin:0 auto;text-align:left;">' + (rows || '<div style="color:#a89e88;font-size:0.9rem;text-align:center;">The roll is being written. Enlist during the First Wave and your name lands here.</div>') + '</div>'
          + '</div>';
        /* Hall-of-Proof-adjacent: after #pf-hallofproof, else the PROOF
           section header (mirrors war-room-ticker.js anchoring). */
        var h = $('pf-v2');
        if (h) {
          var hop = $('pf-hallofproof');
          if (hop && hop.parentNode) { hop.parentNode.insertBefore(el, hop.nextSibling); return; }
          var ph = h.querySelector('.pf-section-head[data-sec="proof"]');
          if (ph && ph.parentNode) { ph.parentNode.insertBefore(el, ph.nextSibling); return; }
          h.appendChild(el); return;
        }
      } catch (e) {}
    }
    try {
      if (!(window.PF && PF.postAction)) { paint([]); return; }
      var to = setTimeout(function () { paint([]); }, 6000);
      PF.postAction('launchweek', 'lw_action', 'launchweek_roll', {}, function (j) {
        try { clearTimeout(to); } catch (e) {}
        var founders = [];
        try { founders = (j && (j.founders || j.roll)) || []; } catch (e2) {}
        paint(founders);
      });
    } catch (e3) { paint([]); }
  }

  /* ---------- Boot ---------- */
  function boot() {
    try {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
        return;
      }
    } catch (e) {}
    var id = ident();
    postStatus({ callsign: id.callsign, device: id.device }, function (j) {
      try {
        if (!j || !j.ok) return; /* dead read: render nothing */
        STATUS = j;
        PHASE = resolvePhase(j);
        if (PHASE === 'dormant') return; /* launched:false, no launch_ts: exit */
        if (PHASE === 'countdown' || PHASE === 'live') renderBanner();
        if (PHASE === 'live' || PHASE === 'ended') {
          /* Post-week: markers + roll persist (legacy); circuit unmounts. */
          if (j.founder === true) renderFounder();
          if (PHASE === 'live') renderCircuit();
          renderRoll();
        }
      } catch (e2) {}
    });
  }
  try { boot(); } catch (e) {}
})();

;

