/* ===== ambush-drop.js ===== */
/* games/ambush-drop.js  |  PF v1.4.3 | S6 AMBUSH DROPS (Wave 3).
   Self-mounting: polls the backend for a live ambush drop and, when one is
   active, mounts a site-wide "INCOMING SUPPLY DROP" banner with the
   extraction countdown and slot counter. Tapping through opens the claim
   panel: one-tap claim -> rarity-styled reveal (matches the loot-crate
   reveal in games/dopamine.js). A spawn ping lands in the site bell inbox
   server-side; this module also nudges locally when it sees a new drop id.
   Reads:  GET ambush_status (public JSONP)   — {ok, live, drop:{id,ends_at,slot_cap,claims,claimed_by_you}}
   Writes: POST {type:"ambush",amb_action:"ambush_open"} (auth-gated, device-limited)
   KILL: ?pf_off=ambush  or  localStorage pf_disabled_v1='["ambush"]'
   GUARDRAILS: everything try/catch; never throws into the page render path.
   No real names, no @shanetheswan, no "donate" in copy. */
(function () {
  'use strict';
  try {
    var PF = window.PF;
    if (!PF || PF.skip('ambush')) { return; }

    var BACKEND = window.PF_BACKEND_URL;
    var POLL_MS = 60000;
    var SEEN_LS = 'pf_ambush_seen_v1';
    var RARITY = {
      common:    { c: '#9aa0a6', label: 'COMMON' },
      rare:      { c: '#4da3ff', label: 'RARE' },
      epic:      { c: '#b45cff', label: 'EPIC' },
      legendary: { c: '#e8b10c', label: 'LEGENDARY' }
    };

    function esc(s) {
      return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }
    function ident() {
      var cs = '', dev = '';
      try { cs = window.PFCallsign ? window.PFCallsign() : ''; } catch (e) {}
      try { dev = window.PFDeviceId ? window.PFDeviceId() : ''; } catch (e) {}
      return { callsign: cs, device: dev };
    }
    function toast(m) {
      try { if (window.PF && PF.toast) { PF.toast(m); return; } } catch (e) {}
      try {
        var t = document.createElement('div'); t.textContent = m;
        t.style.cssText = 'position:fixed;left:50%;top:16%;transform:translateX(-50%);' +
          'background:#c1121f;color:#fff;font:bold 15px monospace;padding:12px 22px;' +
          'border:2px solid #fff;z-index:100001';
        document.body.appendChild(t);
        setTimeout(function () { try { t.remove(); } catch (e2) {} }, 3200);
      } catch (e2) {}
    }

    /* JSONP GET (device is non-sensitive, rides in the query string). */
    function api(action, params, cb) {
      if (!BACKEND) { try { cb(null); } catch (e) {} return; }
      try {
        var fn = 'pfAmbCb' + Math.floor(Math.random() * 1e9), s = document.createElement('script'), done = false;
        function finish(j) {
          if (done) return; done = true;
          try { delete window[fn]; } catch (e) {}
          try { if (s.parentNode) s.parentNode.removeChild(s); } catch (e2) {}
          try { cb(j); } catch (e3) {}
        }
        window[fn] = function (j) { finish(j); };
        s.onerror = function () { finish(null); };
        var q = '?action=' + encodeURIComponent(action);
        for (var k in params) {
          if (params[k] != null && params[k] !== '') q += '&' + encodeURIComponent(k) + '=' + encodeURIComponent(params[k]);
        }
        q += '&callback=' + fn;
        s.src = BACKEND + q;
        document.head.appendChild(s);
        setTimeout(function () { finish(null); }, 12000);
      } catch (e) { try { cb(null); } catch (e2) {} }
    }

    /* CORS POST for the claim (through the shared auth layer when present). */
    function post(type, actionKey, action, params, cb) {
      var body = Object.assign({ type: type }, params || {});
      body[actionKey] = action;
      function done(j) {
        try { cb(j || { ok: false, err: 'Network error.' }); } catch (e) {}
      }
      try {
        if (window.PF && PF.authPost) { PF.authPost(BACKEND, body, done); return; }
        var bodyStr = JSON.stringify(body);
        var o = { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: bodyStr }, c = null, t = null;
        try {
          if (window.AbortController) {
            c = new AbortController(); o.signal = c.signal;
            t = setTimeout(function () { try { c.abort(); } catch (e) {} }, 15000);
          }
        } catch (e) {}
        fetch(BACKEND, o)
          .then(function (r) { return r.json(); })
          .then(function (j) { if (t) { try { clearTimeout(t); } catch (e) {} } done(j); })
          .catch(function () { if (t) { try { clearTimeout(t); } catch (e) {} } done(null); });
      } catch (e) { done(null); }
    }

    function css() {
      try {
        if (document.getElementById('pf-ambush-css')) return;
        var s = document.createElement('style'); s.id = 'pf-ambush-css';
        s.textContent =
          '#pfAmbushBar{position:fixed;left:0;right:0;bottom:0;z-index:99995;' +
            'background:#14060a;border-top:3px solid #c1121f;color:#f5ead6;' +
            'font-family:monospace;padding:10px 14px;display:flex;align-items:center;' +
            'gap:12px;box-shadow:0 -4px 18px rgba(193,18,31,.45);animation:ambpulse 1.6s ease-in-out infinite}' +
          '#pfAmbushBar .amb-tag{background:#c1121f;color:#fff;font-weight:bold;font-size:12px;' +
            'padding:4px 8px;letter-spacing:2px;white-space:nowrap}' +
          '#pfAmbushBar .amb-meta{font-size:12px;line-height:1.5;flex:1;min-width:0}' +
          '#pfAmbushBar .amb-meta b{color:#ffb3b3}' +
          '#pfAmbushBar button{background:#c1121f;color:#fff;border:2px solid #fff;font:bold 13px monospace;' +
            'padding:8px 16px;cursor:pointer;letter-spacing:2px;white-space:nowrap}' +
          '#pfAmbushBar button:disabled{opacity:.45;cursor:default}' +
          '@keyframes ambpulse{0%,100%{box-shadow:0 -4px 18px rgba(193,18,31,.45)}' +
            '50%{box-shadow:0 -4px 28px rgba(193,18,31,.85)}}' +
          '#pfAmbushModal{position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.78);' +
            'display:flex;align-items:center;justify-content:center;padding:18px}' +
          '#pfAmbushModal .amb-card{background:#0d0d0d;border:3px solid #c1121f;max-width:360px;width:100%;' +
            'padding:22px 18px;text-align:center;color:#f5ead6;font-family:monospace}' +
          '#pfAmbushModal .amb-crate{font-size:64px;line-height:1}' +
          '#pfAmbushModal .amb-crate.amb-shake{animation:ambshake .6s ease-in-out}' +
          '#pfAmbushModal .amb-count{font-size:13px;color:#ffb3b3;margin:8px 0}' +
          '#pfAmbushModal .amb-slots{font-size:12px;color:#c9bfa8;margin:4px 0 12px}' +
          '#pfAmbushModal .amb-claim{background:#c1121f;color:#fff;border:2px solid #fff;' +
            'font:bold 15px monospace;padding:12px 22px;cursor:pointer;letter-spacing:2px}' +
          '#pfAmbushModal .amb-claim:disabled{opacity:.45;cursor:default}' +
          '#pfAmbushModal .amb-err{font-size:12px;color:#ff8080;margin-top:10px;min-height:16px}' +
          '#pfAmbushModal .amb-close{background:transparent;border:1px solid #5a1a1a;color:#c9bfa8;' +
            'font:12px monospace;padding:6px 12px;margin-top:10px;cursor:pointer}' +
          /* Loot-crate reveal styling (matches games/dopamine.js dp-reward). */
          '.amb-reward{margin:12px auto 0;max-width:320px;padding:14px;border:3px solid #9aa0a6;' +
            'background:#0d0d0d;text-align:center;animation:ambburst .5s ease-out}' +
          '.amb-reward .amb-rlabel{font:bold 12px monospace;letter-spacing:3px;margin-bottom:6px}' +
          '.amb-reward .amb-rxp{font:bold 34px monospace;color:#f5ead6}' +
          '.amb-reward .amb-rname{font:13px monospace;color:#c9bfa8;margin-top:4px}' +
          '.amb-reward.amb-burst{animation:ambburst .5s ease-out}' +
          '@keyframes ambburst{0%{transform:scale(.6);opacity:0}60%{transform:scale(1.08)}100%{transform:scale(1);opacity:1}}' +
          '@keyframes ambshake{0%,100%{transform:rotate(0)}25%{transform:rotate(-6deg)}' +
            '50%{transform:rotate(5deg)}75%{transform:rotate(-3deg)}}' +
          '@media (prefers-reduced-motion: reduce){#pfAmbushBar,.amb-crate.amb-shake,.amb-reward,.amb-reward.amb-burst{animation:none!important}}';
        document.head.appendChild(s);
      } catch (e) {}
    }

    var ST = null;       // latest ambush_status
    var tickTimer = null;

    function fmtLeft(ms) {
      ms = Math.max(0, ms);
      var s = Math.floor(ms / 1000);
      var m = Math.floor(s / 60), ss = s % 60;
      return (m < 10 ? '0' + m : '' + m) + ':' + (ss < 10 ? '0' + ss : '' + ss);
    }

    function removeBar() {
      try { var b = document.getElementById('pfAmbushBar'); if (b) b.remove(); } catch (e) {}
    }
    function removeModal() {
      try { var m = document.getElementById('pfAmbushModal'); if (m) m.remove(); } catch (e) {}
    }

    function renderBar() {
      removeBar();
      try {
        if (!ST || !ST.live || !ST.drop) return;
        var d = ST.drop;
        var left = d.ends_at - Date.now();
        if (left <= 0) return;
        if (d.claimed_by_you) return;
        var bar = document.createElement('div');
        bar.id = 'pfAmbushBar';
        bar.innerHTML =
          '<span class="amb-tag">INCOMING SUPPLY DROP</span>' +
          '<span class="amb-meta">Extraction in <b id="pfAmbLeft">' + esc(fmtLeft(left)) + '</b><br>' +
          '<span id="pfAmbSlots">' + Number(d.claims || 0) + '/' + Number(d.slot_cap || 200) + ' claimed</span></span>' +
          '<button id="pfAmbGo">GRAB IT</button>';
        document.body.appendChild(bar);
        var go = document.getElementById('pfAmbGo');
        if (go) go.onclick = function () { try { openModal(); } catch (e) {} };
      } catch (e) {}
    }

    function tick() {
      try {
        var el = document.getElementById('pfAmbLeft');
        if (el && ST && ST.live && ST.drop) {
          var left = ST.drop.ends_at - Date.now();
          if (left <= 0) { removeBar(); removeModal(); refresh(); return; }
          el.textContent = fmtLeft(left);
        }
        var m = document.getElementById('pfAmbCount');
        if (m && ST && ST.live && ST.drop) m.textContent = 'Extraction in ' + fmtLeft(ST.drop.ends_at - Date.now());
      } catch (e) {}
    }

    function openModal() {
      try {
        if (!ST || !ST.live || !ST.drop) return;
        removeModal();
        css();
        var d = ST.drop;
        var wrap = document.createElement('div');
        wrap.id = 'pfAmbushModal';
        wrap.innerHTML =
          '<div class="amb-card"><div class="amb-crate" id="ambCrate">&#128230;</div>' +
          '<div class="amb-count" id="pfAmbCount">Extraction in ' + esc(fmtLeft(d.ends_at - Date.now())) + '</div>' +
          '<div class="amb-slots"><span id="pfAmbSlotsM">' + Number(d.claims || 0) + '/' + Number(d.slot_cap || 200) + '</span> claimed — first come, first served.</div>' +
          '<div id="ambRewardSlot"></div>' +
          '<button class="amb-claim" id="ambClaimBtn">CLAIM THE DROP</button>' +
          '<div class="amb-err" id="ambErr"></div>' +
          '<button class="amb-close" id="ambCloseBtn">STAND DOWN</button></div>';
        document.body.appendChild(wrap);
        var close = document.getElementById('ambCloseBtn');
        if (close) close.onclick = removeModal;
        var btn = document.getElementById('ambClaimBtn');
        if (btn) btn.onclick = claim;
      } catch (e) {}
    }

    function claim() {
      try {
        var btn = document.getElementById('ambClaimBtn');
        var err = document.getElementById('ambErr');
        var crate = document.getElementById('ambCrate');
        var id = ident();
        if (!id.callsign || !id.device) {
          if (err) err.textContent = 'Claim a callsign in Enlistment Ranks first — the drop needs somewhere to go.';
          return;
        }
        if (btn) { btn.disabled = true; btn.textContent = 'CRACKING IT OPEN...'; }
        if (crate) { crate.classList.remove('amb-shake'); crate.classList.add('amb-shake'); }
        post('ambush', 'amb_action', 'ambush_open', { callsign: id.callsign, device: id.device }, function (j) {
          try {
            if (crate) crate.classList.remove('amb-shake');
            if (j && j.ok && j.reward) {
              var r = j.reward, rk = RARITY[r.rarity] || RARITY.common;
              var slot = document.getElementById('ambRewardSlot');
              if (slot) {
                slot.innerHTML = '<div class="amb-reward amb-burst" style="border-color:' + rk.c + '">' +
                  '<div class="amb-rlabel" style="color:' + rk.c + '">' + esc(j.consolation ? 'CONSOLATION' : (rk.label + (r.type === 'xp' ? '' : ' — ' + esc(String(r.type || '').toUpperCase())))) + '</div>' +
                  '<div class="amb-rxp">' + (r.xp > 0 ? '+' + Number(r.xp) + ' XP' : esc(String(r.label || 'EMPTY HANDS'))) + '</div>' +
                  '<div class="amb-rname">' + esc(String(r.label || '')) + '</div></div>';
              }
              if (btn) { btn.disabled = true; btn.textContent = 'CLAIMED'; }
              try { document.dispatchEvent(new CustomEvent('pf-ambush-claimed', { detail: { reward: r } })); } catch (e2) {}
              try {
                if (window.PF && PF.dope && (r.rarity === 'epic' || r.rarity === 'legendary')) {
                  PF.dope.confetti(document.getElementById('pfAmbushModal'), 40);
                  if (r.xp > 0) PF.dope.xpFloat(document.getElementById('pfAmbushModal'), '+' + Number(r.xp) + ' XP');
                }
              } catch (e3) {}
              /* Refresh the banner state so it doesn't re-offer a claimed drop. */
              setTimeout(refresh, 1500);
            } else {
              if (btn) { btn.disabled = false; btn.textContent = 'CLAIM THE DROP'; }
              var msg = 'The drop slipped away. Try again.';
              try {
                var e = String((j && j.err) || '');
                if (e === 'already claimed') msg = 'You already grabbed this drop. One per soldier.';
                else if (e === 'drop exhausted') msg = 'All slots claimed — extraction beat you to it.';
                else if (e === 'no drop live') msg = 'Extraction already happened. Watch for the next one.';
              } catch (e2) {}
              if (err) err.textContent = msg;
            }
          } catch (e) {}
        });
      } catch (e) {}
    }

    function seenId() {
      try { return localStorage.getItem(SEEN_LS) || ''; } catch (e) { return ''; }
    }
    function markSeen(id) {
      try { localStorage.setItem(SEEN_LS, id); } catch (e) {}
    }

    function refresh() {
      try {
        var id = ident();
        api('ambush_status', { device: id.device }, function (j) {
          try {
            if (!j || !j.ok) return;
            ST = j;
            /* Bell hook: a brand-new drop id pings locally (the server also
               drops an inbox notification, so the header bell lights up). */
            if (j.live && j.drop && j.drop.id) {
              var prev = seenId();
              if (prev && prev !== j.drop.id && !j.drop.claimed_by_you) {
                toast('INCOMING SUPPLY DROP — claim it before extraction!');
                try { document.dispatchEvent(new CustomEvent('pf-ambush-live', { detail: { drop: j.drop } })); } catch (e2) {}
              }
              markSeen(j.drop.id);
            }
            renderBar();
          } catch (e) {}
        });
      } catch (e) {}
    }

    function init() {
      try {
        css();
        refresh();
        try { setInterval(refresh, POLL_MS); } catch (e) {}
        try { tickTimer = setInterval(tick, 1000); } catch (e2) {}
        try {
          document.addEventListener('visibilitychange', function () {
            if (!document.hidden) refresh();
          });
        } catch (e3) {}
      } catch (e) {}
    }

    /* Site-wide self-mount: fire on DOMContentLoaded (or immediately if the
       document is already parsed). Never throw into the page. */
    try {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { try { init(); } catch (e) {} });
      } else {
        init();
      }
    } catch (e) {}
  } catch (e) {}
})();

;

/* ===== war-room-ticker.js ===== */
/* games/war-room-ticker.js  |  PF v1.4.3 | S5 Live War-Room Ticker (Wave 3).
   Live activity feed — "X just nuked the meter", "Y completed FULL DEPLOYMENT",
   "OPERATION Z LAUNCHED — 2x XP ALL FRONTS". Proof the network is moving while
   you read it. Your callsign on the ticker is its own status hit.
   SELF-MOUNTING + READ-ONLY (ZERO XP — pure visibility economy).
   Mounts: homepage PROOF section (after the fan-vote widget) + /cells page
   (after the cell-war standings widget). If a mount point is missing, fails
   silent — the ticker never breaks page render. ~30s JSONP poll of feed_list.
   "LIVE" badge + events-in-last-hour count. Items deep-link via the event's
   ref.page (relative paths only, validated). Everything wrapped in try/catch.
   KILL: ?pf_off=warrticker  or  localStorage pf_disabled_v1='["warrticker"]' */
(function () {
  'use strict';
  try { init(); } catch (e) {}

  function init() {
    var PF = window.PF;
    if (!PF || PF.skip('warrticker')) return;
    var href = ''; try { href = window.location.href || ''; } catch (e) {}
    if (/\/config\//.test(href)) return;
    try {
      var bd = document.body;
      if (bd && (bd.classList.contains('sqs-edit-mode') || bd.classList.contains('sqs-editing'))) return;
    } catch (e) {}

    var BACKEND = window.PF_BACKEND_URL;
    var KILL = 'warrticker';
    var mounted = false, timer = null, cursor = '', lastHour = 0;

    function esc(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }
    function $(id) { return document.getElementById(id); }
    function safePage(p) {
      p = String(p || '');
      return /^\/[a-zA-Z0-9_\-\/]*$/.test(p) && p.length <= 80 ? p : '';
    }
    function ago(ts) {
      var d = Date.now() - Number(ts);
      if (!(d >= 0)) return 'now';
      if (d < 60000) return 'now';
      if (d < 3600000) return Math.floor(d / 60000) + 'm ago';
      if (d < 86400000) return Math.floor(d / 3600000) + 'h ago';
      return Math.floor(d / 86400000) + 'd ago';
    }
    function tagFor(theme) {
      var t = String(theme || '').toLowerCase()
        .replace(/\s+/g, '-').replace(/[^a-z0-9\-]/g, '').slice(0, 40);
      return t ? '#' + t : '';
    }
    function opMult() {
      try {
        var os = window.PFOperation && window.PFOperation.status;
        var m = os ? Number(os.flash_multiplier) : 0;
        return m > 1 ? m : 0;
      } catch (e) { return 0; }
    }

    /* Event copy — punchy, combative, never invented data. Every value comes
       from the feed_list response (server-sanitized) and is esc()ed. */
    function copyFor(ev) {
      /* W2-D17 (2026-10-04): the actor's equipped custom title rides the
         ticker byline. Backend flag (W6B-1): feed_list events carry title.
         R29 (2026-10-05): subscriber treatment — feed_list events carry
         subscriber:true on the actor (backend-set flag). The marker is a
         text star (\u2605), never emoji. paint() adds the wrt-isub class. */
      var ttl = ev.title ? esc(String(ev.title)).slice(0,40) : '';
      var byline = ttl ? ' \u00AB' + ttl + '\u00BB' : '';
      var sub = !!(ev && ev.subscriber);
      var cs = ev.callsign ? (sub ? '\u2605 ' : '') + esc(ev.callsign) + byline : '';
      var name = esc(ev.name), theme = esc(ev.theme);
      var tag = tagFor(ev.theme);
      switch (ev.type) {
        case 'operation_launch': {
          var m = opMult();
          var t = '\uD83D\uDEA8 OPERATION ' + name + ' LAUNCHED' +
            (m ? ' — ' + m + '\u00D7 XP ALL FRONTS' : '');
          return { text: t, tag: tag, hot: true };
        }
        case 'operation_end':
          return { text: '\uD83C\uDFC1 OPERATION ' + name + ' ENDED', tag: tag, hot: true };
        case 'full_deployment':
          return { text: '\u2694\uFE0F ' + cs + ' completed FULL DEPLOYMENT', tag: '' };
        case 'war_bond': {
          var tier = ev.meta && ev.meta.tier ? Number(ev.meta.tier) : 0;
          return { text: '\uD83D\uDCB0 ' + (cs || 'A comrade') + ' funded the fight' +
            (tier > 0 ? ' — $' + tier + ' War Bond' : ''), tag: '' };
        }
        case 'nuke_blast':
          return { text: '\uD83D\uDCA5 ' + (cs || 'The network') + ' just nuked the meter', tag: '' };
        case 'cell_war_declare':
          return { text: '\u2694\uFE0F Cell ' + name + ' declared war on ' + theme, tag: '' };
        case 'rally_claim':
          return { text: '\uD83D\uDD25 ' + (cs || 'A cell') + ' rallied the cell', tag: '' };
        case 'ambush_grab':
          return { text: '\uD83D\uDCE6 ' + (cs || 'Someone') + ' grabbed the ambush drop', tag: '' };
        /* 6A-R4/R7: narration-bus types — the headline rides ev.name
           (server-sanitized), rendered verbatim so economic wins and civic
           acts narrate exactly as the backend wrote them. */
        case 'econ.auction_won':
          return { text: '\uD83D\uDD28 ' + name, tag: '' };
        case 'econ.stake_claimed':
          return { text: '\uD83D\uDCB0 ' + name, tag: '' };
        case 'econ.venture_resolved':
          return { text: '\uD83C\uDFED ' + name, tag: '' };
        case 'econ.dividend_paid':
          return { text: '\uD83E\uDD1D ' + name, tag: '' };
        case 'econ.contract_claimed':
          return { text: '\uD83D\uDCDC ' + name, tag: '' };
        case 'econ.savings_milestone':
          return { text: '\uD83C\uDFE6 ' + name, tag: '' };
        case 'econ.bond_redeemed':
          return { text: '\uD83C\uDF96\uFE0F ' + name, tag: '' };
        case 'econ.cell_challenge_won':
          return { text: '\uD83C\uDFC6 ' + name, tag: '' };
        case 'civic.intel_confirmed':
          return { text: '\uD83D\uDCE1 ' + name, tag: '', hot: true };
        case 'civic.petition_milestone':
          return { text: '\u270D\uFE0F ' + name, tag: '' };
        case 'civic.proposal_closed':
          return { text: '\uD83D\uDDF3\uFE0F ' + name, tag: '' };
        case 'civic.pledge_made':
          return { text: '\u2705 ' + name, tag: '' };
        case 'civic.index_mover':
          return { text: '\uD83D\uDCC8 ' + name, tag: '' };
        /* 6A-R9: cell treasury -> cause sponsorship. Headline rides ev.name
           (server-sanitized via narrate.js), rendered verbatim. */
        case 'cell.sponsored':
          return { text: '\uD83C\uDFDB\uFE0F ' + name, tag: '' };
        /* R24 (2026-10-05): cause-pool funding ceremony — the backend's
           maybeCelebrateCause emits civic.cause_funded once per pool, the
           headline riding ev.name ("CAUSE <NAME> FULLY FUNDED"). */
        case 'civic.cause_funded':
          return { text: '\uD83C\uDFC6 ' + name, tag: '', hot: true };
        /* R29 (2026-10-04): subscription -> ticker event. Backend emitter
           (W6B-1, flagged): feed_list type subscription/subscribe with meta
           {creator, amount_per_week}. Perk mechanics need Shane's call. */
        case 'subscription':
        case 'subscribe': {
          var creator = esc((ev.meta && ev.meta.creator) || ev.name || 'a creator');
          var perWk = (ev.meta && ev.meta.amount_per_week) ? Number(ev.meta.amount_per_week) : 0;
          return { text: '\uD83D\uDCB0 ' + (cs || 'A comrade') + ' is now funding ' + creator +
            (perWk > 0 ? ' \u2014 ' + perWk.toLocaleString() + ' XP/week' : ''), tag: '' };
        }
        /* Redistribution Layer (2026-10-05): settlement + spoils events.
           Copies verbatim from the redistribution spec §1.10 — every number
           rides ev.meta (emitted by the backend); the ticker never invents. */
        case 'gambit_settled': {
          var gwin = esc((ev.meta && ev.meta.winner) || ev.callsign || 'A fighter');
          var gtithe = (ev.meta && ev.meta.tithe != null) ? Number(ev.meta.tithe) : 0;
          return { text: '\u2694\uFE0F ' + gwin + ' won the gambit — ' +
            gtithe.toLocaleString() + ' XP tithed to the war chest', tag: '' };
        }
        case 'raid_spoils': {
          var rcell = esc((ev.meta && ev.meta.cell) || ev.name || 'A cell');
          var ramt = (ev.meta && ev.meta.amount != null) ? Number(ev.meta.amount) : 0;
          return { text: '\uD83D\uDCE6 ' + rcell + ' left ' + ramt.toLocaleString() +
            ' XP on the line — spoils to the cell treasury', tag: '' };
        }
        case 'draw_won': {
          var dwin = esc((ev.meta && ev.meta.winner) || ev.callsign || 'A fighter');
          var dshare = (ev.meta && ev.meta.winnerShare != null) ? Number(ev.meta.winnerShare) : 0;
          var dchest = (ev.meta && ev.meta.chestShare != null) ? Number(ev.meta.chestShare) : 0;
          return { text: '\uD83C\uDF97\uFE0F ' + dwin + ' won the Solidarity Draw — ' +
            dshare.toLocaleString() + ' XP, ' + dchest.toLocaleString() +
            ' XP to the war chest', tag: '' };
        }
        case 'forecast_settled': {
          var fpool = (ev.meta && ev.meta.pool != null) ? Number(ev.meta.pool) : 0;
          return { text: '\uD83D\uDCCA ' + name + ' resolved — ' +
            fpool.toLocaleString() + ' XP redistributed to the winners', tag: '' };
        }
        default: {
          var label = String(ev.type || '').replace(/_/g, ' ');
          return { text: '\u2022 ' + (cs ? cs + ' — ' : '') + esc(label), tag: '' };
        }
      }
    }

    function api(cb) {
      if (!BACKEND) { cb(null); return; }
      var fn = 'pfWrtCb' + Math.floor(Math.random() * 1e9);
      var s = document.createElement('script'), done = false;
      function finish(j) {
        if (done) return; done = true;
        try { delete window[fn]; } catch (e) {}
        if (s.parentNode) s.parentNode.removeChild(s);
        cb(j);
      }
      window[fn] = function (j) { finish(j); };
      s.onerror = function () { finish(null); };
      var q = '?action=feed_list&limit=20' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : '');
      s.src = BACKEND + q + '&callback=' + fn;
      document.head.appendChild(s);
      setTimeout(function () { finish(null); }, 12000);
    }

    function paint(j) {
      var root = $('pf-warrticker');
      if (!root) return;
      var list = $('pf-wrt-list'), cnt = $('pf-wrt-hour');
      if (!j || !j.ok) {
        if (list && !list.children.length)
          list.innerHTML = '<div class="wrt-empty">Ticker unreachable — retrying</div>';
        return;
      }
      lastHour = Number(j.hour_count) || 0;
      if (cnt) cnt.textContent = lastHour + ' in the last hour';
      var evs = (j.events || []).slice(0, 12);
      if (!evs.length && !list.children.length) {
        list.innerHTML = '<div class="wrt-empty">Quiet on the front — for now.</div>';
        return;
      }
      var h = '';
      for (var i = 0; i < evs.length; i++) {
        var ev = evs[i], c = copyFor(ev);
        var page = ev.ref ? safePage(ev.ref.page) : '';
        /* R29 (2026-10-05): subscriber actions get distinct treatment.
           (wrt-isub — not wrt-sub, which is the ticker subtitle's class.) */
        var subCls = (ev && ev.subscriber) ? ' wrt-isub' : '';
        var open = page ? '<a class="wrt-item' + subCls + '" href="' + page + '">' : '<span class="wrt-item' + subCls + '">';
        var close = page ? '</a>' : '</span>';
        h += open +
          '<span class="wrt-copy">' + c.text +
          (c.tag ? ' <span class="wrt-tag">' + esc(c.tag) + '</span>' : '') + '</span>' +
          '<span class="wrt-ago">' + ago(ev.ts) + '</span>' +
          close;
      }
      list.innerHTML = h;
    }

    function tick() {
      try {
        if (window.PF && PF.hidden && PF.hidden()) return;
        api(paint);
      } catch (e) {}
    }

    /* Keep the ticker glued after its anchor widget even when that widget
       lazy-mounts after us (fail-silent if the anchor never appears). */
    function reposition() {
      try {
        var el = $('pf-warrticker');
        if (!el || !el.parentNode) return;
        var h = document.getElementById('pf-v2');
        if (h) {
          var fv = h.querySelector('section[data-game="fan-vote"]');
          if (fv && fv.nextSibling !== el) h.insertBefore(el, fv.nextSibling);
          return;
        }
        var cp = document.getElementById('pf-cells-page');
        if (cp) {
          var cw = cp.querySelector('section[data-game="cell-war"]');
          if (cw && cw.nextSibling !== el) cp.insertBefore(el, cw.nextSibling);
        }
      } catch (e) {}
    }

    function tryMount() {
      if (mounted) { reposition(); return true; }
      var parent = null, ref = null;
      var h = document.getElementById('pf-v2');
      if (h) {
        /* Homepage: PROOF section. Anchor on the fan-vote widget; fall back
           to right after the PROOF section header until it lazy-mounts. */
        var ph = h.querySelector('.pf-section-head[data-sec="proof"]');
        if (!ph) return false;
        parent = h;
        var fv = h.querySelector('section[data-game="fan-vote"]');
        ref = fv ? fv.nextSibling : ph.nextSibling;
      } else {
        var cp = document.getElementById('pf-cells-page');
        if (!cp) return false;
        parent = cp;
        /* /cells "sidebar" slot: alongside the cell-war standings. Falls back
           to the end of the page mount until standings mount. */
        var cw = cp.querySelector('section[data-game="cell-war"]');
        ref = cw ? cw.nextSibling : null;
      }
      var el = document.createElement('div');
      el.id = 'pf-warrticker';
      el.innerHTML =
        '<style>' +
        '#pf-warrticker{background:#0a0a0a;border:3px solid #c1121f;padding:22px 20px;' +
        'max-width:680px;margin:18px auto;color:#f5ead6;font-family:Arial,sans-serif;box-sizing:border-box}' +
        '#pf-warrticker .wrt-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px}' +
        '#pf-warrticker .wrt-kicker{font-size:12px;letter-spacing:4px;color:#e5383b;font-weight:800}' +
        '#pf-warrticker .wrt-title{font-family:\'Arial Black\',Arial,sans-serif;font-size:22px;' +
        'letter-spacing:2px;text-transform:uppercase}' +
        '#pf-warrticker .wrt-live{display:inline-flex;align-items:center;gap:6px;background:#c1121f;' +
        'color:#fff;font-size:11px;font-weight:800;letter-spacing:2px;padding:3px 10px}' +
        '#pf-warrticker .wrt-dot{width:8px;height:8px;border-radius:50%;background:#4caf50;' +
        'animation:wrtPulse 2s infinite}' +
        '@keyframes wrtPulse{0%,100%{opacity:1}50%{opacity:.35}}' +
        '#pf-warrticker .wrt-hour{margin-left:auto;font-size:12px;color:#a89e88}' +
        '#pf-warrticker .wrt-sub{font-size:13px;color:#a89e88;margin-bottom:14px}' +
        '#pf-warrticker .wrt-item{display:flex;align-items:baseline;gap:10px;padding:9px 10px;' +
        'border-top:1px solid #2a2a2a;color:#f5ead6;text-decoration:none;font-size:14px}' +
        /* R29 (2026-10-05): subscriber actions — gold inset bar + tinted ground. */
        '#pf-warrticker .wrt-item.wrt-isub{box-shadow:inset 3px 0 0 #d4af37;background:#141008}' +
        '#pf-warrticker a.wrt-item:hover{background:#161616}' +
        '#pf-warrticker .wrt-copy{flex:1;line-height:1.4}' +
        '#pf-warrticker .wrt-tag{color:#e5383b;font-weight:700}' +
        '#pf-warrticker .wrt-ago{font-size:11px;color:#a89e88;white-space:nowrap}' +
        '#pf-warrticker .wrt-empty{padding:16px 4px;color:#a89e88;font-size:14px;text-align:center}' +
        '@media(max-width:520px){#pf-warrticker{padding:16px 12px}#pf-warrticker .wrt-title{font-size:18px}}' +
        '@media(prefers-reduced-motion:reduce){#pf-warrticker .wrt-dot{animation:none}}' +
        '</style>' +
        '<div class="wrt-head">' +
        '<span class="wrt-kicker">WAR-ROOM</span>' +
        '<span class="wrt-title">Live Ticker</span>' +
        '<span class="wrt-live"><span class="wrt-dot" aria-hidden="true"></span>LIVE</span>' +
        '<span class="wrt-hour" id="pf-wrt-hour"></span>' +
        '</div>' +
        '<div class="wrt-sub">The network, moving. Make the reel.</div>' +
        '<div id="pf-wrt-list"><div class="wrt-empty">Tuning the wire&hellip;</div></div>';
      if (ref) parent.insertBefore(el, ref);
      else parent.appendChild(el);
      mounted = true;
      tick();
      if (!timer) {
        timer = setInterval(function () {
          try {
            if (window.PF && PF.hidden && PF.hidden()) return;
            reposition();
            api(paint);
          } catch (e) {}
        }, 30000);
      }
      return true;
    }

    /* Mount when our slot exists; the 30s poller doubles as the retry loop
       for lazy-mounting pages. Nothing ever throws into the page. */
    try { if (!tryMount()) {
      setInterval(function () { try { tryMount(); } catch (e) {} }, 30000);
    } } catch (e) {}
  }
})();

